sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.hod-team-leaves-page {
  max-width: 1350px;
  margin: 30px auto;
  padding: 0 20px;
  font-family: Arial, sans-serif;
  color: #0f1b45;
}

.page-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 24px;
}

.page-header h2 {
  margin: 0 0 6px;
  font-size: 28px;
  font-weight: 700;
}

.page-header p {
  margin: 0;
  color: #7c859a;
}

.back-link {
  color: #1769e0;
  text-decoration: none;
}

.summary-row {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 14px;
  margin-bottom: 22px;
}

.summary-card {
  background: #ffffff;
  border: 1px solid #e4e8ef;
  border-radius: 12px;
  padding: 16px;
}

.summary-card span {
  display: block;
  color: #7c859a;
  font-size: 12px;
  margin-bottom: 6px;
}

.summary-card strong {
  font-size: 25px;
}

.table-card {
  background: #ffffff;
  border: 1px solid #e4e8ef;
  border-radius: 14px;
  padding: 22px;
  box-shadow: 0 3px 10px rgba(0,0,0,.04);
}

.table-title {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-bottom: 16px;
  border-bottom: 1px solid #edf0f4;
}

.table-title h3 {
  margin: 0 0 4px;
  font-size: 20px;
}

.table-title span {
  color: #7c859a;
  font-size: 13px;
}

.search-input {
  width: 260px;
  border: 1px solid #dfe4eb;
  border-radius: 8px;
  padding: 9px 12px;
  outline: none;
}

.leave-table {
  width: 100%;
  border-collapse: collapse;
}

.leave-table th {
  text-align: left;
  padding: 14px 10px;
  background: #f7f9fc;
  font-size: 12px;
  white-space: nowrap;
}

.leave-table td {
  padding: 14px 10px;
  border-bottom: 1px solid #edf0f4;
  font-size: 13px;
  vertical-align: top;
}

.status-pill {
  display: inline-block;
  padding: 5px 10px;
  border-radius: 14px;
  font-size: 11px;
  font-weight: 600;
  white-space: nowrap;
}

.status-hod {
  background: #fff1d9;
  color: #c87500;
}

.status-hr {
  background: #fff1d9;
  color: #c87500;
}

.status-approved {
  background: #e6f7ef;
  color: #16875d;
}

.status-rejected {
  background: #fdeaea;
  color: #c83f3f;
}

.status-cancelled {
  background: #eef0f4;
  color: #687083;
}

.empty-row {
  text-align: center;
  color: #8b93a5;
  padding: 28px !important;
}

.table-responsive {
  overflow-x: auto;
}

@media (max-width: 1000px) {
  .summary-row {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 700px) {
  .page-header {
    display: block;
  }

  .back-link {
    display: inline-block;
    margin-top: 12px;
  }

  .table-title {
    display: block;
  }

  .search-input {
    width: 100%;
    margin-top: 12px;
  }
}

sp_widget.script:
(function() {

    data.departmentName = "";
    data.departmentCode = "";
    data.requests = [];

    data.totalCount = 0;
    data.pendingHodCount = 0;
    data.pendingHrCount = 0;
    data.approvedCount = 0;
    data.rejectedCount = 0;

    var standardDepartmentId = "";
    var customDepartmentId = "";
    var departmentCode = "";


    // ----------------------------------
    // 1. LOGGED-IN HOD DEPARTMENT
    // ----------------------------------

    var userGR = new GlideRecord('sys_user');

    if (userGR.get(gs.getUserID())) {

        standardDepartmentId =
            userGR.getValue('department') || "";

        data.departmentName =
            userGR.getDisplayValue('department') || "";
    }

    if (!standardDepartmentId)
        return;


    // ----------------------------------
    // 2. STANDARD DEPARTMENT CODE
    // cmn_department
    // ----------------------------------

    var deptGR = new GlideRecord('cmn_department');

    if (deptGR.get(standardDepartmentId)) {

        departmentCode =
            deptGR.getValue('id') || "";

        data.departmentCode =
            departmentCode;
    }

    if (!departmentCode)
        return;


    // ----------------------------------
    // 3. MAP TO CUSTOM DEPARTMENT
    // ----------------------------------

    var customDeptGR =
        new GlideRecord(
            'x_snc_unified_hr_0_department'
        );

    customDeptGR.addQuery(
        'department_code',
        departmentCode
    );

    customDeptGR.setLimit(1);
    customDeptGR.query();

    if (customDeptGR.next()) {

        customDepartmentId =
            customDeptGR.getUniqueValue();
    }

    if (!customDepartmentId)
        return;


    // ----------------------------------
    // 4. GET ALL DEPARTMENT REQUESTS
    // ----------------------------------

    var leaveGR =
        new GlideRecord(
            'x_snc_unified_hr_0_leave_request'
        );

    leaveGR.addQuery(
        'department',
        customDepartmentId
    );

    leaveGR.orderByDesc('applied_on');
    leaveGR.query();


    while (leaveGR.next()) {

        var statusValue =
            leaveGR.getValue('status') || "";

        data.totalCount++;

        if (statusValue == 'pending_hod')
            data.pendingHodCount++;

        else if (statusValue == 'pending_hr')
            data.pendingHrCount++;

        else if (statusValue == 'approved')
            data.approvedCount++;

        else if (statusValue == 'rejected')
            data.rejectedCount++;


        data.requests.push({

            number:
                leaveGR.getDisplayValue('number'),

            employee:
                leaveGR.getDisplayValue('requested_by'),

            leave_type:
                leaveGR.getDisplayValue('leave_type'),

            start_date:
                leaveGR.getDisplayValue('start_date'),

            end_date:
                leaveGR.getDisplayValue('end_date'),

            days:
                leaveGR.getDisplayValue(
                    'number_of_leave_days'
                ),

            status:
                leaveGR.getDisplayValue('status'),

            status_value:
                statusValue,

            hod_remarks:
                leaveGR.getValue('hod_remarks') || "",

            hr_remarks:
                leaveGR.getValue('hr_remarks') || ""

        });
    }

})();
